mapper.select:
select 
from t_r_user
where sso_provider = #{ssoProvider}
  and sso_id = #{ssoId}
limit 1

select count(*)
from t_r_user
where username = #{username}

select 
from t_r_user
where not exists (
    select 1 from t_r_workspace_member m
    where m.workspace_id = #{workspaceId}
      and m.user_id = t_r_user.id
)

    and username like concat('%', #{keyword}, '%')

order by username asc
limit #{limit}
